    if m.hypersonic then s = s * 3 end
    if m.mirv then s = s * 1.4 end
    return s
end
function B.choose()
    local pick = val("b_missile", "Best")
    local list = {}
    for _, m in ipairs(D.Cfg and D.Cfg.Missiles or {}) do
        if B.unlocked(m, "Missile") and (tonumber(m.damage) or 0) > 0 and (S.cool["m_" .. m.key] or 0) < os.clock() then list[#list + 1] = m end
    end
    if pick ~= "Best" and pick ~= "Cheapest" and pick ~= "Strongest" then
        for _, m in ipairs(list) do
            if m.name == pick then return m end
        end
        return nil
    end
    table.sort(list, function(a, b) return B.price(a.key) < B.price(b.key) end)
    if pick == "Cheapest" then return list[1] end
    if pick == "Strongest" then
        local best
        for _, m in ipairs(list) do
            if M.num("Inv_" .. m.key) >= B.salvo() or B.price(m.key) * B.salvo() <= B.budget() then
                if not best or B.power(m) > B.power(best) then best = m end
            end
        end
        return best or list[1]
    end
    local tgt = B.targets()[1]
    if not tgt then return list[1] end
    local rate, hp = B.perDamage(tgt)
    local best, top = nil, 0
    for _, m in ipairs(list) do
        local owned = M.num("Inv_" .. m.key) >= B.salvo()
        if owned or B.price(m.key) * B.salvo() <= B.budget() then
            local v = math.min(tonumber(m.damage) or 0, hp) * rate * 0.85
            local p = owned and v or v - B.price(m.key)
            if p > top then best, top = m, p end
        end
    end
    return best
end
function B.perDamage(plot)
    local pay = D.Cfg and D.Cfg.Pay
    if not pay then return 0, 0 end
    local hq = tonumber(plot:GetAttribute("OwnerHQ")) or 1
    local bot = plot:GetAttribute("IsBot") == true
    local mult = bot and pay.BotKillBM or pay.HumanKillBM
    local sum, hp, n = 0, 0, 0
    for _, b in ipairs(M.structures(plot)) do
        if b:GetAttribute("Kind") == "Building" and b:GetAttribute("Rubble") ~= true then
            local row = rawget(D.Cfg.BuildingByKey, b:GetAttribute("Key"))
            local maxHp = tonumber(b:GetAttribute("MaxHealth")) or 0
            if row and maxHp > 0 then
                local ok, bm = pcall(D.Cfg.BM, math.min(rawget(row, "tier") or 1, hq))
                if ok and bm then
                    sum += mult * bm / maxHp
                    hp += maxHp
                    n += 1
                end
            end
        end
    end
    if n == 0 then return 0, 0 end
    local rate = sum / n
    if not bot and hq + 2 <= M.num("HQ") then rate *= tonumber(pay.PunchDownMult) or 0.25 end
    return rate, hp / n
end
function B.threats(plot)
    local out, now = {}, M.now()
    for _, b in ipairs(M.structures(plot)) do
        if b:GetAttribute("Kind") == "Defense" and (tonumber(b:GetAttribute("Health")) or 0) > 0 and b:GetAttribute("Rubble") ~= true and (tonumber(b:GetAttribute("EmpUntil")) or 0) <= now then
            local row = D.Cfg and D.Cfg.DefenseByKey and D.Cfg.DefenseByKey[b:GetAttribute("Key")]
            if row and row.range and row.chance then
                out[#out + 1] = { pos = b:GetPivot().Position, range = row.range, chance = row.chance }
            end
        end
    end
    return out
end
function B.risk(threats, pos)
    local sum = 0
    for _, t in ipairs(threats) do
        local dx, dz = pos.X - t.pos.X, pos.Z - t.pos.Z
        local d = math.sqrt(dx * dx + dz * dz)
        if d <= t.range then sum += t.chance * (1 - 0.35 * d / t.range) end
    end
    return sum
end
function B.pending(id)
    local p = id and S.aimed and S.aimed[id]
    if not p then return 0 end
    if os.clock() > p[2] then
        S.aimed[id] = nil
        return 0
    end
    return p[1]
end
function B.reserve(id, dmg)
    if not id then return end
    S.aimed = S.aimed or {}
    S.aimed[id] = { B.pending(id) + dmg, os.clock() + 20 }
end
function B.rated(plot, n, force)
    local threats, list = (force or on("b_avoid")) and B.threats(plot) or {}, {}
    local now = M.now()
    local noPay = D.Cfg and tonumber(D.Cfg.RebuiltNoPaySeconds) or 600
    for _, b in ipairs(M.structures(plot)) do
        local kind, hp = b:GetAttribute("Kind"), tonumber(b:GetAttribute("Health")) or 0
        local rebuilt = tonumber(b:GetAttribute("RebuiltAt")) or 0
        local id = b:GetAttribute("Id")
        hp -= B.pending(id)
        if hp > 0 and b:GetAttribute("Rubble") ~= true and kind ~= "Missile" and (kind == "Building" or on("b_defense")) and (rebuilt <= 0 or now - rebuilt >= noPay) then
            local pos = b:GetPivot().Position
            list[#list + 1] = { pos = pos, hp = hp, risk = B.risk(threats, pos), id = id }
        end
    end
    table.sort(list, function(a, b)
        if a.risk ~= b.risk then return a.risk < b.risk end
        return a.hp < b.hp
    end)
    local out, sum, ids = {}, 0, {}
    for i = 1, math.min(n, #list) do
        out[i] = list[i].pos
        ids[i] = list[i].id
        sum += list[i].risk
    end
    return out, #out > 0 and sum / #out or 0, ids
end
function B.count(name)
    S.hc = S.hc or {}
    local c = S.hc[name]
    if c and os.clock() - c[2] > 600 then S.hc[name] = nil c = nil end
    return c and c[1] or 0
end
function B.noteHit(name)
    S.hc = S.hc or {}
    S.hc[name] = { B.count(name) + 1, os.clock() }
end
function B.placedMissiles(plot)
    local out = {}
    local now = M.now()
    for _, b in ipairs(M.structures(plot)) do
        if b:GetAttribute("Kind") == "Missile" and (tonumber(b:GetAttribute("Health")) or 1) > 0 and b:GetAttribute("Rubble") ~= true and (tonumber(b:GetAttribute("ReadyAt")) or 0) <= now then
            local k = b:GetAttribute("Key")
            if k then out[k] = (out[k] or 0) + 1 end
        end
    end
    return out
end
function B.targets()
    local out = {}
    local f = Workspace:FindFirstChild("Plots")
    if not f then return out end
    local now, mode, ally = M.now(), val("b_mode", "Both"), M.attr("Alliance")
    local selfShield = M.num("ForcefieldUntil") > now
    local mine = M.plot()
    if mine and (tonumber(mine:GetAttribute("ShieldUntil")) or 0) > now then selfShield = true end
    for _, p in ipairs(f:GetChildren()) do
        local owner, hq = p:GetAttribute("OwnerUserId"), tonumber(p:GetAttribute("OwnerHQ")) or 0
        local bot = p:GetAttribute("IsBot") == true or (tonumber(owner) or 0) < 0
        local ok = owner and owner ~= 0 and owner ~= lp.UserId and hq > 0 and (S.skip[p.Name] or 0) < os.clock() and not B.paidOut(p.Name)
        ok = ok and p:GetAttribute("Ghost") ~= true and (tonumber(p:GetAttribute("ShieldUntil")) or 0) <= now
        if ok and bot and mode == "Players" then ok = false end
        if ok and not bot then
            if mode == "Bots" or selfShield then ok = false end
            local a = p:GetAttribute("Alliance")
            if type(a) == "string" and a ~= "" and a == ally then ok = false end
            if on("b_rookie") and p:GetAttribute("Rookie") == true then ok = false end
        end
        if ok then out[#out + 1] = p end
    end
    local score = val("b_pick", "Best")
    local worth = function(p) return tonumber(p:GetAttribute("NetWorth")) or 0 end
    if score == "Richest" then
        table.sort(out, function(a, b) return worth(a) > worth(b) end)
    elseif score == "Weakest" then
        table.sort(out, function(a, b) return worth(a) < worth(b) end)
    else
        local myHQ = M.num("HQ")
        local rated = {}
        for _, p in ipairs(out) do
            local _, risk = B.rated(p, 4, true)
            local v = 1 / (1 + risk * 3)
            if score == "Best" then
                v = v * math.sqrt(worth(p) + 1) / (1 + B.count(p.Name) / 6)
                if p:GetAttribute("IsBot") ~= true and (tonumber(p:GetAttribute("OwnerHQ")) or 0) + 2 <= myHQ then v = v * 0.25 end
            end
            rated[p] = v
        end
        table.sort(out, function(a, b) return rated[a] > rated[b] end)
    end
    return out
end
function B.aimPoints(plot, n)
    return (B.rated(plot, n))
end
function B.stock(plot, m, salvo)
    local have = B.placedMissiles(plot)[m.key] or 0
    if have >= salvo then return have end
    local need = salvo - have
    local inv = M.num("Inv_" .. m.key)
    if inv < need then
        local n = math.min(10, need - inv)
        if B.price(m.key) * n <= B.budget() and M.cool("buymissile", 0.8) then
            local r = M.inv("Shop", "buy", { key = m.key, n = n })
            if M.isOk(r) then
                S.bought += n
            else
                LOG("buy refused", m.key, M.why2(r))
                S.cool.buymissile = os.clock() + 3
                if not M.why2(r):find("moment") and not M.why2(r):find("fast") then S.cool["m_" .. m.key] = os.clock() + 90 end
            end
        end
        inv = M.num("Inv_" .. m.key)
    end
    local count = math.min(need, inv)
    for _, c in ipairs(G.yard(plot, count)) do
        if not RUNNING then break end
        if G.placeItem(plot, m.key, c[1], c[2]) then have += 1 end
        task.wait(0.15)
    end
    return have
end
function B.cycle()
    local plot = M.plot()
    if not plot then S.task = __T["No island"] return end
    local m = B.choose()
    if not m then S.task = __T["No profitable rocket"] return end
    local salvo = B.salvo()
    S.task = __T["Loading "] .. tostring(m.name)
    local open = B.targets()
    local any = false
    for _, t in ipairs(open) do
        if #B.aimPoints(t, 1) > 0 then any = true break end
    end
    if not any then
        S.task = __T["No paying targets"]
        S.dryAt = S.dryAt or os.clock()
        if on("b_hop") and os.clock() - S.dryAt >= val("b_hopwait", 20) and M.cool("hop", 45) then
            S.task = __T["Hopping server"]
            LOG("auto hop")
            P.hop(true)
        end
        return
    end
    S.dryAt = nil
    if B.flightCap() - B.inFlight() < salvo then S.task = __T["Rockets in the air"] return end
    local have = B.stock(plot, m, salvo)
    if have <= 0 then S.task = __T["Need cash for missiles"] return end
    if have < salvo then
        S.loadSince = S.loadSince or os.clock()
        if os.clock() - S.loadSince < 10 then S.task = __T["Loading full salvo"] return end
    end
    local w0 = os.clock()
    while RUNNING and M.num("MissilesReady") < math.min(have, salvo) and os.clock() - w0 < 3.5 do task.wait(0.1) end
    local ready = M.num("MissilesReady")
    if ready < 1 then S.task = __T["Missiles arming"] return end
    S.loadSince = nil
    local keys = {}
    for k, n in pairs(B.placedMissiles(plot)) do
        for _ = 1, n do
            if k == m.key then table.insert(keys, 1, k) else keys[#keys + 1] = k end
        end
    end
    if #keys == 0 then keys = { m.key } end
    local targets = B.targets()
    if #targets == 0 then S.task = __T["No targets"] return end
    local want, pick, fallback = math.min(ready, salvo), nil, nil
    for _, tgt in ipairs(targets) do
        local n = #B.aimPoints(tgt, want)
        if n >= want then
            pick = tgt
            break
        end
        if n > 0 and not fallback then fallback = tgt end
    end
    if not pick and B.inFlight() > 0 then S.task = __T["Rockets in the air"] return end
    pick = pick or fallback
    for _, tgt in ipairs(pick and { pick } or {}) do
        local pts, _, ids = B.rated(tgt, want)
        if #pts > 0 then
            local shots = {}
            for i, p in ipairs(pts) do shots[i] = { key = keys[i] or keys[1], target = p } end
            S.task = __T["Firing at "] .. tostring(tgt:GetAttribute("DisplayName"))
            local r = M.inv("Launch", { shots = shots })
            if M.isOk(r) then
                S.salvos += 1
                S.shots += type(r.launched) == "table" and #r.launched or 0
                S.lastTarget = tgt:GetAttribute("DisplayName")
                B.noteHit(tgt.Name)
                for _, id in ipairs(ids or {}) do B.reserve(id, tonumber(m.damage) or 0) end
                S.flights = S.flights or {}
                S.plotOf = S.plotOf or {}
                for _, id in ipairs(type(r.launched) == "table" and r.launched or {}) do
                    S.flights[id] = tgt.Name
                    S.flyAt = S.flyAt or {}
                    S.flyAt[id] = os.clock()
                    S.plotOf[id] = tgt.Name
                end
            else
                LOG("launch refused", tgt.Name, M.why2(r))
                if not M.why2(r):find("ready") then S.skip[tgt.Name] = os.clock() + 20 end
            end
            return
        end
    end
    S.task = __T["No buildings to hit"]
end
task.spawn(function()
    while RUNNING do
        local ok, e = pcall(function()
            if not M.ready() then
                S.task = M.why()
            elseif on("b_auto") then
                B.cycle()
            else
                S.task = __T["Idle"]
            end
        end)
        if not ok then LOG("bomb err", tostring(e)) end
        local wait = on("b_auto") and val("b_delay", 3) or 0.5
        local t0 = os.clock()
        while RUNNING and os.clock() - t0 < wait do task.wait(0.1) end
    end
end)
local E = {}
function E.hqCost()
