function E.bestBuilding()
    local hqC = E.hqCost()
    local cash = B.spend()
    local best, top = nil, 0
    local list = {}
    for _, it in pairs(D.Cfg and D.Cfg.BuildingByKey or {}) do
        local k = rawget(it, "key")
        if type(k) == "string" and not k:find("^HQ_") and k ~= "OilRig" and not rawget(it, "water") and B.unlocked(it, "Building") and (S.cool["b_" .. k] or 0) < os.clock() then
            list[#list + 1] = it
            local r = rawget(it, "rung") or 0
            if r > top then top = r end
        end
    end
    for _, it in ipairs(list) do
        local k, r = rawget(it, "key"), rawget(it, "rung") or 0
        local p = B.price(k)
        local allow = r >= top - 2 and p <= cash and (not hqC or cash >= hqC or p <= cash * 0.4)
        if M.num("Inv_" .. k) > 0 or allow then
            if not best or r > (rawget(best, "rung") or 0) then best = it end
        end
    end
    return best
end
function E.wonder(plot)
