        if k and M.num("Wonder_" .. k) == 0 and M.num("WonderBuildEnd_" .. k) <= 0 and need <= hq and (S.cool["w_" .. k] or 0) < os.clock() and cost <= B.spend() and (not hqC or B.spend() >= hqC or cost * 2 <= hqC) then
            local x, z = G.spot(plot, rawget(w, "w") or 12, rawget(w, "d") or 12)
