                S.built += 1
                LOG("wonder", k)
                return true
            end
            LOG("wonder refused", k, M.why2(r))
            S.cool["w_" .. k] = os.clock() + 60
            return false
        end
    end
    return false
end
function E.swapWorst(plot, it)
    local worst, wr
    for _, b in ipairs(M.structures(plot)) do
        if b:GetAttribute("Kind") == "Building" and b:GetAttribute("Rubble") ~= true then
            local row = rawget(D.Cfg.BuildingByKey, b:GetAttribute("Key"))
            local r = row and rawget(row, "rung") or 0
            if not wr or r < wr then worst, wr = b, r end
        end
    end
    if not worst or wr >= (rawget(it, "rung") or 0) - 2 then return false end
    local r = M.inv("Build", "sell", { id = worst:GetAttribute("Id") })
    if not M.isOk(r) then
        LOG("sell refused", M.why2(r))
        S.cool.build = os.clock() + 20
        return false
    end
    return true
end
function E.income(plot)
    if not on("u_build") or not M.cool("build", 0.6) then return false end
    local n = 0
    for _, b in ipairs(M.structures(plot)) do
        if b:GetAttribute("Kind") == "Building" then n += 1 end
    end
    local it = E.bestBuilding()
    if not it then return false end
    if n >= (D.Cfg and D.Cfg.MaxIncomeBuildings or 60) and not E.swapWorst(plot, it) then return false end
    return E.buyAndPlace(plot, rawget(it, "key"), it)
end
function E.attacked()
    return M.attr("UnderAttack") == true or os.clock() - (S.incomingAt or -999) < 45
end
function E.shield(plot)
    if not on("u_shield") or not E.attacked() or not M.cool("shield", 3) then return false end
    local now = M.now()
    if M.num("ForcefieldUntil") > now or (tonumber(plot:GetAttribute("ShieldUntil")) or 0) > now or M.num("ShieldCashReadyAt") > now then return false end
    local price = M.num("ShieldPrice_cash_30")
    if price <= 0 or price > B.spend() then return false end
    local r = M.inv("Forcefield", "buyCash", "cash_30")
    LOG("shield", M.isOk(r), M.why2(r))
    if M.isOk(r) then S.shields = (S.shields or 0) + 1 else S.cool.shield = os.clock() + 20 end
