function E.upgradeDefense(plot)
    if not M.cool("defup", 1.5) then return false end
    local maxMk = D.Cfg.DefenseMk and #D.Cfg.DefenseMk or 3
    local margin = E.attacked() and 1.2 or 3
    local hq, best, bestCost = M.num("HQ"), nil, nil
    for _, b in ipairs(M.structures(plot)) do
        if b:GetAttribute("Kind") == "Defense" and b:GetAttribute("Rubble") ~= true then
            local row = D.Cfg.DefenseByKey[b:GetAttribute("Key")]
            local mk, id = tonumber(b:GetAttribute("Mk")) or 1, b:GetAttribute("Id")
            if row and id and mk < maxMk and (S.cool["up" .. id] or 0) < os.clock() then
                local need = gcall(D.Econ.DefenseUnlockHQ, row, mk + 1)
                local cost = gcall(D.Econ.DefensePrice, row, mk + 1)
                if need and cost and need <= hq and cost * margin <= B.spend() and (not bestCost or cost > bestCost) then best, bestCost = b, cost end
            end
        end
    end
    if not best then return false end
    local id = best:GetAttribute("Id")
    local r = M.inv("Build", "upgrade", { id = id })
    if M.isOk(r) then
        S.built += 1
        LOG("defense up", best:GetAttribute("Key"))
        return true
    end
    LOG("upgrade refused", best:GetAttribute("Key"), M.why2(r))
    S.cool["up" .. id] = os.clock() + 300
    return false
end
function E.defense(plot)
    if not on("u_def") or not M.cool("def", E.attacked() and 0.4 or 1) or not D.Econ then return false end
    local counts = {}
    for _, b in ipairs(M.structures(plot)) do
        if b:GetAttribute("Kind") == "Defense" then
            local k = b:GetAttribute("Key")
            counts[k] = (counts[k] or 0) + 1
        end
    end
    local hq, best = M.num("HQ"), nil
    for _, it in ipairs(D.Cfg.Defenses or {}) do
        local cap = gcall(D.Econ.DefenseCap, it.key, hq, M.num("Rebirths")) or 0
        if B.unlocked(it, "Defense") and (counts[it.key] or 0) < cap and (S.cool["b_" .. it.key] or 0) < os.clock() and not it.water then
            local p = B.price(it.key)
            if M.num("Inv_" .. it.key) > 0 or p * (E.attacked() and 1.2 or 3) <= B.spend() then
                if not best or p > B.price(best.key) then best = it end
            end
        end
    end
    if not best then
        if E.upgradeDefense(plot) then return true end
        S.cool.def = os.clock() + (E.attacked() and 1 or 8)
        return false
    end
    return E.buyAndPlace(plot, best.key, best)
end
function E.oil()
