        if cost and cost * 2 <= B.spend() and (S.cool["oil" .. slot] or 0) < os.clock() then
            local r = M.inv("OilRig", lv <= 0 and "build" or "upgrade", slot)
            if M.isOk(r) then
                S.built += 1
