local W = {}
function W.claim(what, id, label)
    if not M.cool("claim", 1.15) then return false end
    local r
    if id ~= nil then r = M.inv("Rewards", what, id) else r = M.inv("Rewards", what) end
    if M.isOk(r) then
        S.claimed += 1
        LOG("claimed", label or what, tostring(id))
    else
        LOG("claim refused", what, tostring(id), M.why2(r))
        S.cool["c_" .. what .. tostring(id)] = os.clock() + 45
    end
    return true
end
function W.can(what, id) return (S.cool["c_" .. what .. tostring(id)] or 0) < os.clock() end
function W.tick()
    if on("r_codes") and not S.codesDone then
        S.codesDone = true
        local codes = {}
        for k in pairs(D.Rew and D.Rew.Codes or {}) do codes[#codes + 1] = k end
        if #codes == 0 then codes = { "KABOOM", "NUKE2", "RELEASE", "BOOM", "COMMANDER" } end
        for _, c in ipairs(codes) do
            local r = M.inv("Rewards", "redeem", c)
            LOG("code", c, M.isOk(r), M.why2(r))
            task.wait(1.3)
        end
    end
    if M.num("OfflineOwed") > 0 and W.can("offline") and on("r_daily") and W.claim("offline") then return end
    local raw = M.attr("RewardsJson")
    if type(raw) ~= "string" or raw == "" then return end
    local ok, j = pcall(function() return HttpService:JSONDecode(raw) end)
    if not ok or type(j) ~= "table" then return end
    if on("r_daily") then
        if type(j.st) == "table" and j.st.r == true and W.can("streak") and W.claim("streak") then return end
        for _, id in ipairs(type(j.gr) == "table" and j.gr or {}) do
            if W.can("gift", id) and W.claim("gift", id) then return end
        end
    end
    if on("r_tasks") then
        for _, m in ipairs(type(j.m) == "table" and j.m or {}) do
            local id = m.id or m.slot
            if m.cl == false and tonumber(m.p) and tonumber(m.c) and m.p >= m.c and W.can("mission", id) and W.claim("mission", id) then return end
        end
        for i, c in ipairs(type(j.ct) == "table" and j.ct or {}) do
            local slot = c.s or c.slot or i
            if tonumber(c.p) and tonumber(c.c) and c.p >= c.c and not c.cl and W.can("contract", slot) and W.claim("contract", slot) then return end
        end
    end
    if on("r_season") and type(j.se) == "table" then
        local done = {}
        for k, t in pairs(type(j.se.cl) == "table" and j.se.cl or {}) do
            done[tostring(t == true and k or t)] = true
        end
        for t = 1, tonumber(j.se.t) or 0 do
            if not done[tostring(t)] and W.can("season", t) and W.claim("season", t) then return end
        end
    end
end
task.spawn(function()
