function P.tp(name)
    local plot
    if name == "My Island" then
        plot = M.plot()
    else
        local f = Workspace:FindFirstChild("Plots")
        plot = f and f:FindFirstChild("Plot" .. name:gsub("Island ", ""))
    end
    local base = plot and plot:FindFirstChild("Base")
    if not base then notify(__T["Not available right now"]) return end
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    rp.FilterDescendantsInstances = { lp.Character }
    for _, o in ipairs({ { 0, 40 }, { 40, 0 }, { -40, 0 }, { 0, -40 }, { 60, 60 }, { -60, -60 } }) do
        local from = base.Position + Vector3.new(o[1], 120, o[2])
        local d = Workspace:Raycast(from, Vector3.new(0, -200, 0), rp)
        if d and d.Normal.Y >= 0.8 and not d.Instance:IsA("Seat") and not d.Instance:IsA("VehicleSeat") then
            local s = d.Position + Vector3.new(0, 3.2, 0)
            local op = OverlapParams.new()
            op.FilterType = Enum.RaycastFilterType.Exclude
            op.FilterDescendantsInstances = { lp.Character }
            local clear = true
            for _, h in ipairs(Workspace:GetPartBoundsInBox(CFrame.new(s + Vector3.new(0, 0.2, 0)), Vector3.new(3, 5.4, 3), op)) do
                if h.CanCollide then clear = false break end
            end
            if clear then M.go(s) return end
        end
    end
    notify(__T["No clear spot there"])
end
function P.hop(small)
    task.spawn(function()
        local order = small and "Asc" or "Desc"
        local ok, data = pcall(function()
            return HttpService:JSONDecode(game:HttpGet("https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=" .. order .. "&excludeFullGames=true&limit=100"))
        end)
        if ok and type(data) == "table" and data.data then
            local pool = {}
            for _, s in ipairs(data.data) do
                if s.id ~= game.JobId and s.playing and s.playing < s.maxPlayers then pool[#pool + 1] = s end
            end
            if small then table.sort(pool, function(a, b) return a.playing < b.playing end) end
            if #pool > 0 then
                local pick = pool[math.random(1, small and math.min(5, #pool) or #pool)]
                if CONFIG.LOADER and CONFIG.LOADER ~= "" and queue_on_teleport then
                    pcall(queue_on_teleport, 'loadstring(game:HttpGet("' .. CONFIG.LOADER .. '"))()')
                end
                TeleportService:TeleportToPlaceInstance(game.PlaceId, pick.id, lp)
                return
            end
        end
        notify(__T["No other server found"])
    end)
end
